characters:
{'edges': [{'voiceActors': [{'id': 118475}], 'node': {'id': 257562, 'name': {'full': 'Hitori Gotou'}, 'image': {'large': 'https://s4.anilist.co/file/anilistcdn/character/large/b257562-Ru35NYPfsqhY.png'}, 'description': 'Gotou Hitori is a shy, gloomy high-schooler who started learning guitar after seeing rock bands on TV, in the hope that she too could become as popular as them. However, after 2 years she has yet to make a single friend or join a band. She instead sits in her closet at home, recording guitar covers and posting them to her YouTube channel, "guitarhero", on which she has amassed a reasonable following.', 'gender': 'Female', 'age': '16'}}, {'voiceActors': [{'id': 126963}], 'node': {'id': 261674, 'name': {'full': 'Nijika Ijichi'}, 'image': {'large': 'https://s4.anilist.co/file/anilistcdn/character/large/b261674-a8tJYvtzqWgC.png'}, 'description': 'An energetic and cheerful second-year high school student. She is the drummer of Kessoku Band and the organizer who takes care of [Hitori](https://anilist.co/character/257562). She has an older sister, [Seika](https://anilist.co/character/289054), who is the manager of the live house "STARRY" and has a special feeling for the live house.', 'gender': 'Female', 'age': '17'}}, {'voiceActors': [{'id': 213951}], 'node': {'id': 264529, 'name': {'full': 'Ryou Yamada'}, 'image': {'large': 'https://s4.anilist.co/file/anilistcdn/character/large/b264529-BvEusZnJLD2Y.png'}, 'description': "A cool and solitary second year of high school. She is in charge of the bass of Kessoku Band. She's the best friend of [Nijika](https://anilist.co/character/261674). Her hobbies are out of the ordinary, and she rejoices when called a weirdo. She lives with a wealthy family, but she spends much of her money on instruments and always runs out of money. She occasionally eats weeds to get rid of her hunger.", 'gender': 'Female', 'age': '17'}}, {'voiceActors': [{'id': 132768}], 'node': {'id': 266041, 'name': {'full': 'Ikuyo Kita'}, 'image': {'large': 'https://s4.anilist.co/file/anilistcdn/character/large/b266041-1HKgjJGP2MmM.png'}, 'description': 'A bright and popular first year of high school. She is in charge of the guitar and vocals of Kessoku Band. She is a cheerful character who likes to interact with people and can talk to her with a smile without hesitation, even when she meets her for the first time. She longs for [Ryo](https://anilist.co/character/264529), and her feelings can go too far. She often takes photos and uploads to Isosta.', 'gender': 'Female', 'age': '16'}}, {'voiceActors': [{'id': 119616}], 'node': {'id': 291639, 'name': {'full': 'Kikuri Hiroi'}, 'image': {'large': 'https://s4.anilist.co/file/anilistcdn/character/large/b291639-VYrixXvuwLqx.png'}, 'description': 'Bassist and vocalist of the band "SICK HACK".

